export const AIGC_NOTICE='本报告展示本次文本的 AI 生成特征与疑似片段占比。分段标签不能证明文字来源，结果不替代学校指定的检测报告。';
const safeLimit=(value,fallback)=>Number.isInteger(value)&&value>0?value:fallback;
export function aigcLimits(cap={}){return {maxCharacters:safeLimit(cap.maxCharacters,50000),maxPartCharacters:safeLimit(cap.maxPartCharacters,5000),userDailyCharacters:safeLimit(cap.userDailyCharacters,100000),userDailyLimit:safeLimit(cap.userDailyLimit,10)};}
export function validateAigcText(input,cap={}){const text=String(input??''),limits=aigcLimits(cap),characters=Array.from(text).length;if(!text.trim())throw Error('请先粘贴或导入需要鉴别的正文。');if(characters>limits.maxCharacters)throw Error(`正文超过 ${limits.maxCharacters.toLocaleString('en-US')} 字符，请分章节提交；不会自动截断。`);let partCount=0,units=0;for(const character of text){if(units+character.length>limits.maxPartCharacters){partCount++;units=0;}units+=character.length;}return {text,characters,partCount:partCount+(units?1:0)};}
export const aigcLabel=label=>({aigc:'偏 AI 生成表达',ugc:'偏人工表达',mixed:'分段倾向不一致',undetermined:'暂不能明确判定'}[label]||'暂不能明确判定');
export function aigcPublicError(error){if(error?.publicMessage)return error.publicMessage;if(error?.status===401)return '登录状态已失效，请登录后读取原任务。';if(error?.status===403)return '账户或访问权限已变化，请重新进入此功能。';if(error?.status===429)return '当前鉴别额度已用完或请求较多，请稍后再试。';if(error?.status===413)return '正文超过服务上限，请分章节提交。';if(error?.status===409)return '原任务与当前资料不一致，请先读取原任务，再重新确认。';if(error?.status===400||error?.status===422)return '请检查正文长度与处理授权后重试。';if(error?.status===404)return '暂未找到此账户的任务，请刷新最近任务。';return '鉴别服务暂未完成请求，请读取原任务状态，避免重复提交。';}
export function normalizeAigcResult(value){if(!value||!/^[-\w]{1,100}$/.test(String(value.id||''))||!['running','completed','failed'].includes(value.status))throw Error('invalid detection result');const whole=number=>Number.isInteger(number)&&number>=0?number:0,parts=(Array.isArray(value.parts)?value.parts:[]).slice(0,100).map((part,index)=>{const label=['aigc','ugc','undetermined'].includes(part.label)?part.label:'undetermined',confidence=label!=='undetermined'&&typeof part.confidence==='number'&&Number.isFinite(part.confidence)&&part.confidence>=0&&part.confidence<=100?part.confidence:null;return {index:whole(part.index??index),start:whole(part.start),end:whole(part.end),characters:whole(part.characters),...(part.skipped===true&&label==='undetermined'&&confidence===null?{skipped:true}:{}),label:confidence===null?'undetermined':label,confidence};});const counts={aigc:0,ugc:0,undetermined:0};parts.forEach(part=>{if(part.skipped!==true)counts[part.label]++;});const partCount=whole(value.partCount),completedParts=whole(value.completedParts),fullyCompleted=value.status==='completed'&&partCount>0&&parts.length===partCount&&completedParts===partCount;let verdict='undetermined';if(fullyCompleted&&value.conclusive!==false&&value.verdict!=='undetermined'&&!counts.undetermined&&(counts.aigc>0||counts.ugc>0)){verdict=counts.aigc&&counts.ugc?'mixed':counts.aigc?'aigc':'ugc';}const date=value=>typeof value==='string'&&/^\d{4}-\d{2}-\d{2}T/.test(value)&&Number.isFinite(Date.parse(value))?new Date(value).toISOString():'';return {id:value.id,title:typeof value.title==='string'?value.title.slice(0,200):'',reportAvailable:value.reportAvailable===true,reportReady:value.reportReady===true,status:value.status,characters:whole(value.characters),partCount,completedParts,parts,counts,verdict,fullyCompleted,createdAt:date(value.createdAt),updatedAt:date(value.updatedAt)};}

// A character-weighted coverage of actual chunk labels, never a conversion of
// provider confidence into authorship probability or a sentence-level AI rate.
export function aigcLabelCoverage(value){
 const item=normalizeAigcResult(value);let offset=0,aiCharacters=0,humanCharacters=0,unknownCharacters=0;
 const valid=item.fullyCompleted&&item.parts.every((part,index)=>{const ok=part.index===index&&part.start===offset&&part.end>part.start&&part.end<=item.characters&&part.characters===part.end-part.start;offset=part.end;if(!part.skipped){if(part.label==='aigc')aiCharacters+=part.characters;else if(part.label==='ugc')humanCharacters+=part.characters;else unknownCharacters+=part.characters;}return ok;})&&offset===item.characters;
 const testedCharacters=aiCharacters+humanCharacters+unknownCharacters,available=Boolean(valid&&item.verdict!=='undetermined'&&unknownCharacters===0&&testedCharacters>0);
 return {available,ratio:available?aiCharacters/testedCharacters:null,aiCharacters,humanCharacters,unknownCharacters,testedCharacters};
}
